        if ($CliArguments.Count -eq 0) {
            throw 'Missing config action: set, get, or list.'
        }

        $configAction = $CliArguments[0].ToLowerInvariant()
        $operandCount = switch ($configAction) {
            'set' { 2 }
            'get' { 1 }
            'list' { 0 }
            default { throw "Unknown config action: $configAction" }
        }
        if ($CliArguments.Count -lt (1 + $operandCount)) {
            throw "Missing argument for config $configAction."
        }
        $configOperands = @($CliArguments | Select-Object -Skip 1 -First $operandCount)
        $CliArguments = @($CliArguments | Select-Object -Skip (1 + $operandCount))
    }

