    }
    $configDirectory = Split-Path -Parent $configFile
    $config = Read-TaskForgeConfig -Path $configFile
    $defaultDataFile = Join-Path $root 'data/tasks.json'
    $dataFile = if ($options.Contains('data-file')) {
        Resolve-TaskForgePath -Path (Get-RequiredOption -Options $options -Name 'data-file') -BaseDirectory $configDirectory
    }
    elseif ($null -ne $config.dataFile) {
