        $defaultDataFile
    }
    if ($options.Contains('json') -and $options.Contains('no-json')) {
        throw '--json and --no-json cannot be used together.'
    }
    $asJson = if ($options.Contains('no-json')) {
        $false
    }
    elseif ($options.Contains('json')) {
        if ($options['json'] -is [bool]) { $true }
        else { ConvertTo-TaskForgeBoolean -Value ([string]$options['json']) -Name '--json' }
    }
    else {
        [bool]$config.defaultJson
    }

    switch ($Command.ToLowerInvariant()) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'config-file', 'json', 'no-json')
            $title = Get-RequiredOption -Options $options -Name 'title'
            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title.Trim()
                description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'config-file', 'json', 'no-json')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json', 'no-json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'config-file', 'json', 'no-json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'config' {
            Assert-KnownOptions -Options $options -Allowed @('config-file', 'json', 'no-json')
            switch ($configAction) {
                'set' {
                    $key = $configOperands[0]
                    $value = $configOperands[1]
                    if ($key -notin @('dataFile', 'defaultJson')) {
                        throw "Unknown configuration key: $key"
                    }

                    if ($key -eq 'dataFile') {
                        if ([string]::IsNullOrWhiteSpace($value)) {
                            throw 'Configuration key dataFile must be a non-empty string.'
                        }
                        $config.dataFile = $value
                    }
                    else {
                        $config.defaultJson = ConvertTo-TaskForgeBoolean -Value $value -Name 'defaultJson'
                    }

                    Write-TaskForgeConfig -Path $configFile -Config $config
                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $key; value = $config[$key] }) -AsJson $true
                    }
                    elseif ($config[$key] -is [bool]) {
                        "$key = $($config[$key].ToString().ToLowerInvariant())"
                    }
                    else {
                        "$key = $($config[$key])"
                    }
                }
                'get' {
                    $key = $configOperands[0]
                    if ($key -notin @('dataFile', 'defaultJson')) {
                        throw "Unknown configuration key: $key"
                    }

                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $key; value = $config[$key] }) -AsJson $true
                    }
                    elseif ($null -eq $config[$key]) {
                        ''
                    }
                    elseif ($config[$key] -is [bool]) {
                        $config[$key].ToString().ToLowerInvariant()
                    }
                    else {
                        [string]$config[$key]
                    }
                }
                'list' {
                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]$config) -AsJson $true
                    }
                    else {
                        Get-Content -LiteralPath (Join-Path $root 'assets/config.txt')
                        "dataFile = $(if ($null -eq $config.dataFile) { '' } else { $config.dataFile })"
                        "defaultJson = $($config.defaultJson.ToString().ToLowerInvariant())"
                    }
                }
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @('config-file')
            @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--json]
  list [--data-file PATH] [--json]
  complete --id ID [--data-file PATH] [--json]
  remove --id ID [--data-file PATH] [--json]
  config set KEY VALUE [--json]
  config get KEY [--json]
  config list [--json]
  All commands accept --config-file PATH.
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
